      <input type="text" class="otp-box" maxlength="1" inputmode="numeric" pattern="[0-9]">
      <input type="text" class="otp-box" maxlength="1" inputmode="numeric" pattern="[0-9]">
      <input type="text" class="otp-box" maxlength="1" inputmode="numeric" pattern="[0-9]">
      <input type="text" class="otp-box" maxlength="1" inputmode="numeric" pattern="[0-9]">
    </div>

    <div id="countdown" class="countdown">إعادة الإرسال خلال ٠:٤٥</div>

    <button id="verify-btn" class="verify-btn" disabled> territories</button>
  </div>

  <script>
    document.addEventListener('DOMContentLoaded', function () {
      const inputs = document.querySelectorAll('.otp-box');
      const verifyBtn = document.getElementById('verify-btn');
      const countdownEl = document.getElementById('countdown');

      // Auto-advance OTP boxes
      inputs.forEach((input, index) => {
        input.addEventListener('input', function () {
          if (this.value.length === 1) {
            if (index < inputs.length - 1) {
              inputs[index + 1].focus();
            }
          }
        });

        input.addEventListener('keydown', function (e) {
          if (e.key === 'Backspace' && this.value.length === 0) {
            if (index > 0) {
              inputs[index - 1].focus();
            }
          }
        });
      });

      // Enable verify button only when all boxes are filled
      function checkVerifyEnabled() {
        const allFilled = Array.from(inputs).every(input => input.value.length === 1);
        verifyBtn.disabled = !allFilled;
      }
      inputs.forEach(input => {
        input.addEventListener('input', checkVerifyEnabled);
      });

      // Countdown timer
      let seconds = 45;
      function toArabicIndic(num) {
        return num.toString().replace(/\d/g, d => String.fromCharCode(d.charCodeAt(0) + 0x0660));
      }

      function updateCountdown() {
        const minutes = Math.floor(seconds / 60);
        const secs = seconds % 60;
        const minStr = toArabicIndic(minutes);
        const secStr = toArabicIndic(secs);

        if (seconds > 0) {
          countdownEl.textContent = `إعادة الإرسال خلال ${minStr}:${secStr}`;
          seconds--;
        } else {
          countdownEl.textContent = '';
          const resendBtn = document.createElement('button');
          resendBtn.textContent = 'إعادة الإرسال';
          resendBtn.className = 'verify-btn';
          resendBtn.style.cssText = 'width:100%;padding:16px;background-color:#007AFF;color:white;border:none;border-radius:8px;font-size:16px;font-weight:600;cursor:pointer;';
          countdownEl.appendChild(resendBtn);

          resendBtn.addEventListener('click', () => {
            seconds = 45;
            countdownEl.innerHTML = '';
            updateCountdown();
            inputs.forEach(i => i.value = '');
            inputs[0].focus();
            checkVerifyEnabled();
          });
        }
      }

      updateCountdown();
      setInterval(updateCountdown, 1000);

      // Focus first box on load
      inputs[0].focus();
    });
  </script>
